Here is a complete, lightweight Python library to interact with the MythTV Services API (REST API). 

MythTV's backend primarily exposes its API over HTTP on port `6544`. This library uses the popular `requests` module to handle the networking and requests data in JSON format for easy parsing in Python.

### Prerequisites
You will need to install the `requests` library if you haven't already:
```bash
pip install requests
```

### The Library (`mythtv_api.py`)

```python
import requests
from urllib.parse import urljoin

class MythTVAPIException(Exception):
    """Custom exception for MythTV API errors."""
    pass

class BaseService:
    """Base class for specific MythTV API services."""
    def __init__(self, client):
        self.client = client

class DvrService(BaseService):
    """Endpoints related to Digital Video Recording (DVR)."""

    def get_recorded_list(self, descending=True, count=0, start_index=0):
        """Retrieves a list of recorded programs."""
        params = {
            'Descending': 'true' if descending else 'false',
            'Count': count,
            'StartIndex': start_index
        }
        return self.client._get("Dvr/GetRecordedList", params)

    def get_upcoming_list(self):
        """Retrieves a list of upcoming recordings."""
        return self.client._get("Dvr/GetUpcomingList")

    def delete_recording(self, chan_id, start_time, force_delete=False):
        """Deletes a recording."""
        params = {
            'ChanId': chan_id,
            'StartTime': start_time,
            'ForceDelete': 'true' if force_delete else 'false'
        }
        return self.client._post("Dvr/DeleteRecording", params)


class MythService(BaseService):
    """General MythTV backend endpoints."""

    def get_host_name(self):
        """Gets the hostname of the backend."""
        return self.client._get("Myth/GetHostName")

    def get_connection_info(self):
        """Gets database connection info."""
        return self.client._get("Myth/GetConnectionInfo")


class ChannelService(BaseService):
    """Endpoints related to TV Channels."""

    def get_channel_info_list(self, source_id=0, start_index=0, count=0):
        """Retrieves a list of channels."""
        params = {
            'SourceID': source_id,
            'StartIndex': start_index,
            'Count': count
        }
        return self.client._get("Channel/GetChannelInfoList", params)


class MythTVClient:
    """Main client for the MythTV Services API."""

    def __init__(self, host='localhost', port=6544):
        self.base_url = f"http://{host}:{port}/"
        self.headers = {'Accept': 'application/json'}

        # Initialize services
        self.dvr = DvrService(self)
        self.myth = MythService(self)
        self.channel = ChannelService(self)

    def _get(self, endpoint, params=None):
        """Internal method to handle GET requests."""
        url = urljoin(self.base_url, endpoint)
        try:
            response = requests.get(url, params=params, headers=self.headers)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            raise MythTVAPIException(f"API GET request failed: {e}")

    def _post(self, endpoint, data=None):
        """Internal method to handle POST requests."""
        url = urljoin(self.base_url, endpoint)
        try:
            response = requests.post(url, data=data, headers=self.headers)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            raise MythTVAPIException(f"API POST request failed: {e}")
```

### Example Usage

Here is how you would use the library in your code:

```python
from mythtv_api import MythTVClient, MythTVAPIException

def main():
    # Connect to the MythTV backend (replace '192.168.1.100' with your backend IP)
    client = MythTVClient(host='192.168.1.100', port=6544)

    try:
        # 1. Get Backend Hostname
        host_info = client.myth.get_host_name()
        print(f"Connected to Backend: {host_info['String']}")

        # 2. Get the last 5 Recorded TV Shows
        print("\n--- Last 5 Recordings ---")
        recordings = client.dvr.get_recorded_list(count=5)

        # Drill down into the JSON payload
        programs = recordings.get('ProgramList', {}).get('Programs', [])

        for prog in programs:
            title = prog.get('Title')
            sub_title = prog.get('SubTitle', 'No Subtitle')
            start_time = prog.get('StartTime')
            chan_id = prog.get('Channel', {}).get('ChanId')
            print(f"[{chan_id}] {title} - {sub_title} (Recorded: {start_time})")

        # 3. Get Channels list
        print("\n--- Available Channels ---")
        channels = client.channel.get_channel_info_list(count=3)
        chan_list = channels.get('ChannelInfoList', {}).get('ChannelInfos', [])
        for chan in chan_list:
            print(f"{chan.get('ChanNum')}: {chan.get('CallSign')} - {chan.get('ChannelName')}")

    except MythTVAPIException as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()
```

### How to extend this library
The MythTV API is vast (encompassing Guide, Video, Capture, Frontend, etc.). Because of the modular design of this script, adding new endpoints is very easy.

If you look at the [MythTV API Wiki](https://www.mythtv.org/wiki/Services_API), and you want to add `Video/GetVideoList`, you simply add a `VideoService` class:

```python
class VideoService(BaseService):
    def get_video_list(self, descending=False):
        params = {'Descending': 'true' if descending else 'false'}
        return self.client._get("Video/GetVideoList", params)

# Then in __init__ of MythTVClient add:
# self.video = VideoService(self)
```

